start-job.function:
job -> x -> {
	$job.jobPhase('collect');
	$job.jobMessage(#('Collecting the source records.'@en, 'Die Quelldatensätze werden gesammelt.'@de));
	count(1, 6).foreach(i -> {
		sleep(400);
		$job.jobProgress($i, 5);
	});
	$job.jobPhase('draft');
	$job.jobIndeterminate();
	$job.jobMessage(#('Drafting the report.'@en, 'Der Bericht wird entworfen.'@de));
	sleep(1500);
	$job.jobPhase('review');
	$job.jobMessage(#('Reviewing the draft.'@en, 'Der Entwurf wird geprüft.'@de));
	count(1, 4).foreach(i -> {
		sleep(300);
		$job.jobProgress($i, 3);
	});
	#('5 records processed.'@en, '5 Datensätze verarbeitet.'@de);
}
